//! Outbound housing GameEvent encoders for the pinned official ACE snapshot.
//! Provenance: official ACEmulator/ACE 47edade3bd3f6044b676d4eb877c4965c7eda62b,
//! `Source/ACE.Server/Network/GameEvent/Events/GameEventHouse*.cs` and the
//! `Structure/House*.cs`, `RestrictionDB.cs`, `HouseAccess.cs`, `GuestInfo.cs` writers.
//! Golden vectors: `tests/fixtures/housing_output.csv`, generated by
//! `oracle/housing_output_generate.py` from the verbatim ACE writers.
//! Wire layout only: callers supply already-authorized state; no gameplay lookup happens here.
use crate::envelope::message_writer;
use crate::opcode::{GameEventType, GameMessageOpcode};
use crate::social_tables::string;
use crate::{WeenieError, WireError, WirePosition, Writer};

/// ACE record version written by `HouseAccess` and `RestrictionDB` (`0x10000002`).
pub const HOUSE_RECORD_VERSION: u32 = 0x1000_0002;
/// ACE `HouseBitfield.Active`, the default profile bitmask.
pub const HOUSE_BITFIELD_ACTIVE: u32 = 1;
/// ACE `HARBitfield` flags.
pub const HAR_OPEN_HOUSE: u32 = 1;
pub const HAR_ALLEGIANCE_GUESTS: u32 = 2;
pub const HAR_ALLEGIANCE_STORAGE: u32 = 4;
/// ACE `GameEventHouseTransaction` always sends notice type 2.
const HOUSE_TRANSACTION_NOTICE: u32 = 2;
/// Header bucket count for `HouseAccess.GuestList` (`guestComparer = GuidComparer(64)`).
const GUEST_BUCKETS: u32 = 64;
/// Header bucket count for `RestrictionDB` (sent over the wire; not used for ordering).
const RESTRICTION_HEADER_BUCKETS: u32 = 768;
/// Ordering bucket count for `RestrictionDB` (client-side hardcoded value 89).
const RESTRICTION_ORDER_BUCKETS: u32 = 89;

/// ACE `HouseType` (`Undef` 0, `Cottage` 1, `Villa` 2, `Mansion` 3, `Apartment` 4).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(u32)]
pub enum HouseType {
    Undef = 0,
    Cottage = 1,
    Villa = 2,
    Mansion = 3,
    Apartment = 4,
}

/// Bounds for every outbound housing message. All lists and strings are checked before writing.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HousingLimits {
    pub max_message_bytes: usize,
    /// Windows-1252 bytes per string (char count for representable text).
    pub max_string_bytes: usize,
    /// Entries per list, table, or payment set.
    pub max_entries: usize,
}

/// ACE `HousePayment`: one buy or rent requirement.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HousePayment<'a> {
    pub num: i32,
    pub paid: i32,
    pub weenie_id: u32,
    pub name: &'a str,
    pub plural_name: &'a str,
}

/// ACE `HouseProfile` (sent by `GameEventHouseProfile`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HouseProfile<'a> {
    pub dwelling_id: u32,
    pub owner_id: u32,
    pub bitmask: u32,
    pub min_level: i32,
    pub max_level: i32,
    pub min_allegiance_rank: i32,
    pub max_allegiance_rank: i32,
    pub maintenance_free: bool,
    pub house_type: HouseType,
    pub owner_name: &'a str,
    pub buy: &'a [HousePayment<'a>],
    pub rent: &'a [HousePayment<'a>],
}

/// ACE `HouseData` (sent by `GameEventHouseData`).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct HouseData<'a> {
    pub buy_time: u32,
    pub rent_time: u32,
    pub house_type: HouseType,
    pub maintenance_free: bool,
    pub buy: &'a [HousePayment<'a>],
    pub rent: &'a [HousePayment<'a>],
    pub position: WirePosition,
}

/// ACE `GuestInfo` with its guest ID, as one `HouseAccess.GuestList` entry.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HouseGuest<'a> {
    pub id: u32,
    pub item_storage: bool,
    pub name: &'a str,
}

/// ACE `HouseAccess` (sent by `GameEventUpdateHAR`, the guest list).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HouseAccess<'a> {
    pub version: u32,
    pub bitmask: u32,
    pub monarch_id: u32,
    /// Any order. The encoder sorts by ACE `GuidComparer(64)` and rejects duplicate IDs.
    pub guests: &'a [HouseGuest<'a>],
    pub roommates: &'a [u32],
}

/// ACE `RestrictionDB` (the per-object access-control list).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct RestrictionDb<'a> {
    pub version: u32,
    pub open_status: bool,
    pub monarch_id: u32,
    /// `(character id, permission)`: 0 dwelling only, 1 with storage. Any order.
    pub table: &'a [(u32, u32)],
}

/// One outbound housing GameEvent. Each variant maps 1:1 to an ACE GameEventHouse* class.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum HousingEvent<'a> {
    /// 0x021D `GameEventHouseProfile`.
    Profile {
        crystal: u32,
        profile: HouseProfile<'a>,
    },
    /// 0x0225 `GameEventHouseData`.
    Data(HouseData<'a>),
    /// 0x0226 `GameEventHouseStatus`. ACE's default is `WeenieError.BadParam`.
    Status(WeenieError),
    /// 0x0227 `GameEventHouseUpdateRentTime`. ACE always sends 0.
    RentTime(u32),
    /// 0x0228 `GameEventHouseUpdateRentPayment`. ACE always sends an empty list.
    RentPayments(&'a [HousePayment<'a>]),
    /// 0x0248 `GameEventHouseUpdateRestrictions`.
    Restrictions {
        sequence: u8,
        object: u32,
        db: RestrictionDb<'a>,
    },
    /// 0x0257 `GameEventUpdateHAR`.
    AccessList(HouseAccess<'a>),
    /// 0x0259 `GameEventHouseTransaction` (fixed notice type 2).
    Transaction,
    /// 0x0271 `GameEventHouseAvailableHouses`.
    AvailableHouses {
        house_type: HouseType,
        locations: &'a [u32],
        total_available: i32,
    },
}

impl HousingEvent<'_> {
    pub fn event_type(&self) -> GameEventType {
        match self {
            Self::Profile { .. } => GameEventType::HouseProfile,
            Self::Data(_) => GameEventType::HouseData,
            Self::Status(_) => GameEventType::HouseStatus,
            Self::RentTime(_) => GameEventType::UpdateRentTime,
            Self::RentPayments(_) => GameEventType::UpdateRentPayment,
            Self::Restrictions { .. } => GameEventType::HouseUpdateRestrictions,
            Self::AccessList(_) => GameEventType::UpdateHAR,
            Self::Transaction => GameEventType::HouseTransaction,
            Self::AvailableHouses { .. } => GameEventType::AvailableHouses,
        }
    }

    /// Encodes the complete GameEvent message: opcode, object, sequence, event type, body.
    pub fn encode(
        &self,
        object_id: u32,
        sequence: u32,
        limits: HousingLimits,
    ) -> Result<Vec<u8>, WireError> {
        let mut writer = message_writer(GameMessageOpcode::GameEvent);
        writer.u32(object_id);
        writer.u32(sequence);
        writer.u32(self.event_type().0);
        match self {
            Self::Profile { crystal, profile } => {
                writer.u32(*crystal);
                write_profile(&mut writer, profile, limits)?;
            }
            Self::Data(data) => write_data(&mut writer, data, limits)?,
            Self::Status(error) => writer.u32(error.value()),
            Self::RentTime(rent_time) => writer.u32(*rent_time),
            Self::RentPayments(payments) => write_payments(&mut writer, payments, limits)?,
            Self::Restrictions {
                sequence,
                object,
                db,
            } => {
                writer.bytes(&[*sequence]);
                writer.u32(*object);
                write_restrictions(&mut writer, db, limits)?;
            }
            Self::AccessList(access) => write_access(&mut writer, access, limits)?,
            Self::Transaction => writer.u32(HOUSE_TRANSACTION_NOTICE),
            Self::AvailableHouses {
                house_type,
                locations,
                total_available,
            } => {
                writer.u32(*house_type as u32);
                write_u32_list(&mut writer, locations, limits)?;
                writer.u32(*total_available as u32);
            }
        }
        if writer.position() > limits.max_message_bytes {
            return Err(WireError::LimitExceeded);
        }
        Ok(writer.into_bytes())
    }
}

fn bounded_count(count: usize, limits: HousingLimits) -> Result<(), WireError> {
    if count > limits.max_entries || count > u16::MAX as usize {
        return Err(WireError::LimitExceeded);
    }
    Ok(())
}

/// ACE `PackableList.Write(List<uint>)`: signed count (written as u32), then each item.
fn write_u32_list(
    writer: &mut Writer,
    values: &[u32],
    limits: HousingLimits,
) -> Result<(), WireError> {
    bounded_count(values.len(), limits)?;
    writer.u32(values.len() as u32);
    for value in values {
        writer.u32(*value);
    }
    Ok(())
}

/// ACE `HousePaymentExtensions.Write(List<HousePayment>)`: count, then each payment.
fn write_payments(
    writer: &mut Writer,
    payments: &[HousePayment<'_>],
    limits: HousingLimits,
) -> Result<(), WireError> {
    bounded_count(payments.len(), limits)?;
    writer.u32(payments.len() as u32);
    for payment in payments {
        writer.u32(payment.num as u32);
        writer.u32(payment.paid as u32);
        writer.u32(payment.weenie_id);
        string(writer, payment.name, limits.max_string_bytes)?;
        string(writer, payment.plural_name, limits.max_string_bytes)?;
    }
    Ok(())
}

/// ACE `HouseProfileExtensions.Write`.
fn write_profile(
    writer: &mut Writer,
    profile: &HouseProfile<'_>,
    limits: HousingLimits,
) -> Result<(), WireError> {
    writer.u32(profile.dwelling_id);
    writer.u32(profile.owner_id);
    writer.u32(profile.bitmask);
    for value in [
        profile.min_level,
        profile.max_level,
        profile.min_allegiance_rank,
        profile.max_allegiance_rank,
    ] {
        writer.u32(value as u32);
    }
    writer.u32(u32::from(profile.maintenance_free));
    writer.u32(profile.house_type as u32);
    string(writer, profile.owner_name, limits.max_string_bytes)?;
    write_payments(writer, profile.buy, limits)?;
    write_payments(writer, profile.rent, limits)
}

/// ACE `HouseDataExtensions.Write`.
fn write_data(
    writer: &mut Writer,
    data: &HouseData<'_>,
    limits: HousingLimits,
) -> Result<(), WireError> {
    writer.u32(data.buy_time);
    writer.u32(data.rent_time);
    writer.u32(data.house_type as u32);
    writer.u32(u32::from(data.maintenance_free));
    write_payments(writer, data.buy, limits)?;
    write_payments(writer, data.rent, limits)?;
    data.position.write(writer);
    Ok(())
}

/// ACE `PackableHashTable.WriteHeader` (u16 count, u16 buckets) then sorted entries.
/// ACE sorts with `GuidComparer`: by `id % sort_buckets`, then by id.
fn write_table<T>(
    writer: &mut Writer,
    entries: &[(u32, T)],
    header_buckets: u32,
    sort_buckets: u32,
    limits: HousingLimits,
    mut write_value: impl FnMut(&mut Writer, &T) -> Result<(), WireError>,
) -> Result<(), WireError> {
    bounded_count(entries.len(), limits)?;
    let mut sorted: Vec<&(u32, T)> = entries.iter().collect();
    sorted.sort_unstable_by_key(|entry| (entry.0 % sort_buckets, entry.0));
    if sorted.windows(2).any(|pair| pair[0].0 == pair[1].0) {
        return Err(WireError::InvalidEncoding);
    }
    writer.u16(entries.len() as u16);
    writer.u16(header_buckets as u16);
    for entry in sorted {
        writer.u32(entry.0);
        write_value(writer, &entry.1)?;
    }
    Ok(())
}

/// ACE `HouseAccessExtensions.Write(HouseAccess)`.
fn write_access(
    writer: &mut Writer,
    access: &HouseAccess<'_>,
    limits: HousingLimits,
) -> Result<(), WireError> {
    writer.u32(access.version);
    writer.u32(access.bitmask);
    writer.u32(access.monarch_id);
    let guests: Vec<(u32, &HouseGuest<'_>)> = access.guests.iter().map(|g| (g.id, g)).collect();
    write_table(
        writer,
        &guests,
        GUEST_BUCKETS,
        GUEST_BUCKETS,
        limits,
        |w, guest| {
            w.u32(u32::from(guest.item_storage));
            string(w, guest.name, limits.max_string_bytes)
        },
    )?;
    write_u32_list(writer, access.roommates, limits)
}

/// ACE `RestrictionDBExtensions.Write`. The header uses 768 but ordering uses 89.
fn write_restrictions(
    writer: &mut Writer,
    db: &RestrictionDb<'_>,
    limits: HousingLimits,
) -> Result<(), WireError> {
    writer.u32(db.version);
    writer.u32(u32::from(db.open_status));
    writer.u32(db.monarch_id);
    write_table(
        writer,
        db.table,
        RESTRICTION_HEADER_BUCKETS,
        RESTRICTION_ORDER_BUCKETS,
        limits,
        |w, permission| {
            w.u32(*permission);
            Ok(())
        },
    )
}
